int best;

typedef struct { int dy, dx; } Dir;

Dir getDir(int i, int j) {
    int dy = py[j] - py[i];
    int dx = px[j] - px[i];
    // normalize
    int g = abs(dy) > abs(dx) ? abs(dy) : abs(dx);
    // gcd
    int a = abs(dy), b = abs(dx);
    while(b) { int t = b; b = a%b; a = t; }
    if(a == 0) a = 1;
    dy /= a; dx /= a;
    if(dx < 0 || (dx == 0 && dy < 0)) { dy = -dy; dx = -dx; }
    Dir d = {dy, dx};
    return d;
}

Dir lines[10];
int nlines;

void solve(int cnt) {
    if(cnt == n/2) {
        // count parallel pairs
        int score = 0;
        for(int i = 0; i < nlines; i++)
            for(int j = i+1; j < nlines; j++)
                if(lines[i].dy == lines[j].dy && lines[i].dx == lines[j].dx)
                    score++;
        if(score > best) best = score;
        return;
    }
    // find first unused
    int first = -1;
    for(int i = 0; i < n; i++) if(!used[i]) { first = i; break; }
    used[first] = 1;
    for(int j = first+1; j < n; j++) {
        if(!used[j]) {
            used[j] = 1;
            lines[cnt] = getDir(first, j);
            solve(cnt+1);
            used[j] = 0;
        }
    }
    used[first] = 0;
}

