    printf("%d\n", best);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

typedef struct {
    ll x, y;
} Point;

static int cmp_ll(const void *a, const void *b) {
    ll x = *(const ll *)a;
    ll y = *(const ll *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    Point *p = (Point *)malloc((size_t)n * sizeof(Point));
    for (int i = 0; i < n; ++i) {
        scanf("%lld %lld", &p[i].x, &p[i].y);
    }

    /* 
       Key fact:
       For a fixed direction d, points can be partitioned into lines parallel to d.
       If on such lines the counts are c1, c2, ..., ck, then the maximum number of
       pairs whose connecting segments are parallel to d equals:
           sum floor(ci / 2) + floor((number of odd ci) / 2)
         = floor(n / 2) - (number of odd ci mod 2 ? 0 : 0) actually simplifies to
           floor(n / 2) - impossible constraints handled by pairing odds across lines.
       But a segment between two points is parallel to d iff the two points lie on a
       line perpendicular to some normal vector n and have equal projection on n.
       So for a chosen normal vector n, points are grouped by value x*n.x + y*n.y.
       Any pair within the same group gives a segment parallel to d.
       Therefore for that direction, maximum number of parallel segments is
           sum floor(group_size / 2).

       It is enough to test normals determined by pairs of points:
       if an optimal direction exists with at least one parallel segment, then some
       pair realizes that direction, so its normal is perpendicular to that pair.
    */

    int answer = 0;

    if (n >= 2) {
        ll *vals = (ll *)malloc((size_t)n * sizeof(ll));

        for (int i = 0; i < n; ++i) {
            for (int j = i + 1; j < n; ++j) {
                ll nx = p[j].y - p[i].y;      /* normal to segment (dx,dy) is (dy,-dx) */
                ll ny = -(p[j].x - p[i].x);

                for (int k = 0; k < n; ++k) {
                    vals[k] = p[k].x * nx + p[k].y * ny;
                }

                qsort(vals, (size_t)n, sizeof(ll), cmp_ll);

                int cur = 0;
                int cnt = 1;
                for (int k = 1; k < n; ++k) {
                    if (vals[k] == vals[k - 1]) {
                        cnt++;
                    } else {
                        cur += cnt / 2;
                        cnt = 1;
                    }
                }
                cur += cnt / 2;

                if (cur > answer) answer = cur;
            }
        }

        free(vals);
    }

    printf("%d\n", answer);

    free(p);
    return 0;
}

