pair<int,int> normalize(int dx, int dy) {
    if (dx == 0) return {0, 1};
    if (dy == 0) return {1, 0};
    int g = gcd(abs(dx), abs(dy));
    dx /= g; dy /= g;
    if (dx < 0) { dx = -dx; dy = -dy; }
    return {dx, dy};
}

void backtrack(vector<pair<int,int>>& slopes) {
    int first = -1;
    for (int i = 0; i < n; i++) {
        if (!used[i]) {
            first = i;
            break;
        }
    }
    if (first == -1) {
        // all points paired
        unordered_map<long long, int> cnt;
        for (auto &s : slopes) {
            long long key = ((long long)s.first << 32) ^ (unsigned int)s.second;
            cnt[key]++;
        }
        int parallelPairs = 0;
        for (auto &kv : cnt) {
            parallelPairs += kv.second / 2;
        }
        best = max(best, parallelPairs);
        return;
    }
    used[first] = true;
    for (int j = first + 1; j < n; j++) {
        if (!used[j]) {
            used[j] = true;
            int dx = pts[j].x - pts[first].x;
            int dy = pts[j].y - pts[first].y;
            slopes.push_back(normalize(dx, dy));
            backtrack(slopes);
            slopes.pop_back();
            used[j] = false;
        }
    }
    used[first] = false;
}

