public class Main {
    static class Point {
        int x, y;
        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        Point[] points = new Point[n];
        for (int i = 0; i < n; i++) {
            points[i] = new Point(sc.nextInt(), sc.nextInt());
        }

        boolean[] used = new boolean[n];
        int[] best = new int[1];
        dfs(points, used, new ArrayList<>(), best);
        System.out.println(best[0]);
    }

    static void dfs(Point[] points, boolean[] used, List<int[]> pairs, int[] best) {
        int n = points.length;
        int first = -1;
        for (int i = 0; i < n; i++) {
            if (!used[i]) {
                first = i;
                break;
            }
        }
        if (first == -1) {
            best[0] = Math.max(best[0], countParallel(pairs, points));
            return;
        }
        used[first] = true;
        for (int j = first + 1; j < n; j++) {
            if (!used[j]) {
                used[j] = true;
                pairs.add(new int[]{first, j});
                dfs(points, used, pairs, best);
                pairs.remove(pairs.size() - 1);
                used[j] = false;
            }
        }
        used[first] = false;
    }

    static int countParallel(List<int[]> pairs, Point[] points) {
        int m = pairs.size();
        int count = 0;
        for (int i = 0; i < m; i++) {
            for (int j = i + 1; j < m; j++) {
                if (isParallel(points, pairs.get(i), pairs.get(j))) {
                    count++;
                }
            }
        }
        return count;
    }

    static boolean isParallel(Point[] pts, int[] p1, int[] p2) {
        int dx1 = pts[p1[0]].x - pts[p1[1]].x;
        int dy1 = pts[p1[0]].y - pts[p1[1]].y;
        int dx2 = pts[p2[0]].x - pts[p2[1]].x;
        int dy2 = pts[p2[0]].y - pts[p2[1]].y;
        // cross product zero means parallel
        return (long) dx1 * dy2 == (long) dy1 * dx2;
    }
}

